function showWork(i){selected=i;const w=works[i];dialog.innerHTML=`<button class="close" aria-label="Close artwork">×</button><div class="detail-layout"><div class="detail-image"><img src="assets/${w.file}.webp" alt="${w.description}"></div><div class="detail-copy"><span class="eyebrow">BONGA RAJA / ${String(i+1).padStart(2,'0')}</span><h2 id="detail-title">${w.name}</h2><p class="detail-medium">${w.medium}</p><p>${w.description}</p><div class="availability"><span>COLLECT THIS WORK</span><p>Enquire directly for price and availability.</p><a class="contact-link" href="mailto:tridiveshmishra@gmail.com?subject=${encodeURIComponent('Artwork enquiry — '+w.name)}&amp;body=${encodeURIComponent('Hello Bonga Raja, I am interested in the artwork described as “'+w.name+'” in your online collection ('+w.medium+'). Could you share its price, dimensions and availability?')}">Enquire by email</a><a class="contact-link secondary" href="https://wa.me/918310371519?text=${encodeURIComponent('Hello Bonga Raja, I would like to enquire about “'+w.name+'” ('+w.medium+') in your online collection. Could you share its price and availability?')}" target="_blank" rel="noopener noreferrer">Ask on WhatsApp</a></div><div class="detail-nav"><button id="previous" aria-label="Previous artwork">Previous</button><span>${i+1} / ${works.length}</span><button id="next" aria-label="Next artwork">Next</button></div></div></div>`;wireClose();dialog.querySelector('#previous').onclick=()=>showWork((selected+works.length-1)%works.length);dialog.querySelector('#next').onclick=()=>showWork((selected+1)%works.length);if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');}
function wireClose(){dialog.querySelector('.close').onclick=()=>dialog.close();}
dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
dialog.addEventListener('keydown',e=>{if(!dialog.querySelector('.detail-nav'))return;if(e.key==='ArrowRight'){e.preventDefault();showWork((selected+1)%works.length)}if(e.key==='ArrowLeft'){e.preventDefault();showWork((selected+works.length-1)%works.length)}});
document.querySelectorAll('[data-work]').forEach(card=>card.onclick=()=>showWork(Number(card.dataset.work)));
document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('.art-card').forEach(card=>{card.hidden=button.dataset.filter!=='All work'&&card.dataset.medium!==button.dataset.filter;if(!card.hidden)count++});document.querySelector('#result-count').textContent=`${count} artworks shown`;});
